function* sfMeshCompute(i){const gfEpoch=SF.epoch,gfVersion=GF.versions[i]||0;if(lightBounds||!lightBuilt)rebuildLight();let cx=i%N,cz=Math.floor(i/N),a=[],water=[];for(let z=cz*C;z<(cz+1)*C;z++)for(let x=cx*C;x<(cx+1)*C;x++){for(let y=0;y<=meshTops[z*W+x];y++){let b=get(x,y,z);if(!b)continue;let d=D[b],light=lightAt(x,y,z);if(b===14){waterMesh(water,x,y,z);continue;}if(workshopMesh(a,x,y,z,b))continue;if(farmBlockMesh(a,x,y,z,b))continue;if(javaStaticMesh(a,x,y,z,b))continue;if(d.shape==='slab'){slabMesh(a,x,y,z,b);continue;}if(d.plant){if(b===16){cube(a,x+.43,y,z+.43,.14,.65,.14,'oak_log',light);cube(a,x+.41,y+.59,z+.41,.18,.17,.18,'torchFlame',1,2,1.4);}else{if(d.crop){let stage=Math.min(3,Math.floor((clock-(crops[key3(x,y,z)]??clock))/160*4));crossed(a,x,y,z,d.stages[stage],light,1);continue;}let stage=b===29?Math.min(7,Math.floor((clock-(crops[key3(x,y,z)]??clock))/160*8)):0;crossed(a,x,y,z,b===29?'wheat_stage'+stage:d.tex,light,b===29?1:.8);}continue;}if(b===31){for(let f=0;f<6;f++)face(a,x+.0625,y,z+.0625,.875,.875,.875,f,blockTex(b,f,x,y,z),light);continue;}if(d.bed){for(let f=0;f<6;f++)face(a,x,y,z,1,.5625,1,f,blockTex(b,f,x,y,z),light);continue;}if(d.door){cube(a,x,y,z,d.open?.1875:1,1,d.open?1:.1875,d.tex,light);continue;}for(let f=0;f<6;f++){let dd=FACES[f].d,n=get(x+dd[0],y+dd[1],z+dd[2]);if((b===14&&n===14)||(n===b&&d.cutout))continue;if(opaque(n)||solid(n)&&!D[n].cutout&&!D[n].door&&!D[n].partial)continue;face(b===14?water:a,x,y,z,1,b===14?.89:b===28?.94:1,1,f,blockTex(b,f,x,y,z),vertexLight(x,y,z,f),b===14?1:blockFaceKind(b,f,x,y,z),1,b===14?null:aoFor(x,y,z,f));}}yield;}if(gfEpoch!==SF.epoch||gfVersion!==(GF.versions[i]||0)){GF.stats.staleRejected++;dirty.add(i);return;}let c=chunks[i]||{buffer:gl.createBuffer(),waterBuffer:gl.createBuffer()};c.count=a.length/8;c.waterCount=water.length/8;if(SS_VAO)SS_VAO.bindVertexArrayOES(null);c.sfX=0;c.sfZ=0;c.gfVersion=gfVersion;ssUpload(c,a);ssUpload(c,water,true);chunks[i]=c;}

function sfLoading(text){SF.loading=true;paused=true;activeUI='loading';left=false;rightHeld=false;keys={};let el=$('streamLoadOverlay');el.classList.remove('hidden');$('streamLoadText').textContent=text;}
function sfLoadingDone(){SF.loading=false;$('streamLoadOverlay')?.classList.add('hidden');last=performance.now();}
function sfWarmCache(text,world=null){if(typeof Worker==='undefined')return Promise.resolve(false);sfLoading('Preparing streamed terrain in the background…');return new Promise(resolve=>{let worker,timer,cache=new Map(),plan;try{let url=URL.createObjectURL(new Blob([SF_WORKER_SOURCE],{type:'text/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);let finish=ok=>{clearTimeout(timer);worker.terminate();if(ok)SF.warm={seed:text,cache,plan};resolve(ok);};timer=setTimeout(()=>finish(false),30000);worker.onerror=e=>{e.preventDefault();finish(false);};worker.onmessage=e=>{let m=e.data;if(m.plan)plan=m.plan;else if(m.done)finish(true);else if(m.q){cache.set(m.cx+','+m.cz,m.q);$('streamLoadText').textContent='Preparing terrain: '+Math.round(cache.size/256*100)+'% ('+cache.size+'/256 chunks)';}};worker.postMessage({config:{seed:seedHash(text),H:128,SEA:40,biomeGeneration:world?(world.biomeGeneration||0):3,wbForcedBiome:world?(world.wbForcedBiome??-1):Number($('wbBiomePreset')?.value??-1),I:Object.fromEntries(Object.entries(I).map(([k,v])=>[k,{block:v.block,fluidBlock:v.fluidBlock}])),D:Object.fromEntries(Object.entries(D).map(([k,v])=>[k,{plant:v.plant}])),OP:Object.fromEntries(Object.keys(D).map(k=>[k,lightOpacity(+k)])),EM:Object.fromEntries(Object.entries(D).map(([k,v])=>[k,v.emission||0])),OC:Object.fromEntries(Object.keys(D).map(k=>[k,opaque(+k)]))}});worker.postMessage({start:world?{origin:[world.ox,world.oz],spawn:world.spawn}:{}});}catch(e){worker?.terminate();resolve(false);}});}
