function sfInstallLoadingUI(){
 let oldCreate=$('createBtn').onclick,oldContinue=$('continueBtn').onclick;
 $('createBtn').onclick=async()=>{if(SF.loading)return;if($('worldSize').value!=='infinite')return oldCreate();if(COOP.role!=='solo'){toast('Leave co-op before creating a streamed solo world.');return;}if(started&&!confirm('Create a new world? Export your current world first to keep it.'))return;let btn=$('createBtn');btn.disabled=true;try{let text=$('seedInput').value.trim()||'WORLD-'+Math.floor(Math.random()*0xFFFFFFFF).toString(36).toUpperCase();$('seedInput').value=text;await sfWarmCache(text);$('streamLoadText').textContent='Installing terrain and preparing lighting…';await new Promise(requestAnimationFrame);newWorld();}catch(e){toast('Generation failed: '+e.message);console.error(e);}finally{btn.disabled=false;sfLoadingDone();}};
 $('continueBtn').onclick=async()=>{if(SF.loading)return;try{if(!started){let s=JSON.parse(localStorage.getItem(STORE));if(s?.terrainVersion===6)await sfWarmCache(s.seed,s.streamWorld);}oldContinue();}catch(e){toast('Could not load save: '+e.message);}finally{sfLoadingDone();}};
 window.addEventListener('keydown',e=>{if(SF.loading){e.preventDefault();e.stopImmediatePropagation();}},true);
}
sfInstallLoadingUI();
